<?php /** @var list<array<string,mixed>> $clients */ /** @var list<array<string,mixed>> $projects */ /** @var list<array<string,mixed>> $templates */ ?>
<p class="eyebrow"><a href="/agreements">Agreements</a></p><h1>New agreement</h1>
<form method="post" action="/agreements" class="panel form-grid" novalidate><?= csrf_field() ?>
    <div class="field"><label for="c">Client</label><select id="c" name="client" required><option value="">Choose…</option><?php foreach ($clients as $c) : ?><option value="<?= e($c['public_id']) ?>"<?= old('client') === $c['public_id'] ? ' selected' : '' ?>><?= e($c['company_name'] ?: $c['contact_name']) ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="p">Project <span class="muted">(optional)</span></label><select id="p" name="project"><option value="">None</option><?php foreach ($projects as $p) : ?><option value="<?= e($p['public_id']) ?>"<?= old('project') === $p['public_id'] ? ' selected' : '' ?>><?= e($p['code']) ?> · <?= e($p['title']) ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="t">Title</label><input id="t" name="title" required maxlength="200" value="<?= e(old('title')) ?>"></div>
    <div class="field"><label for="m">How will it be signed?</label><select id="m" name="mode"><option value="online"<?= old('mode', 'online') === 'online' ? ' selected' : '' ?>>Online: the client signs in their portal</option><option value="physical"<?= old('mode') === 'physical' ? ' selected' : '' ?>>On paper: I will upload the signed scan</option></select></div>
    <div class="field"><label for="tp">Template <span class="muted">(online agreements)</span></label><select id="tp" name="template"><option value="">Write the text myself</option><?php foreach ($templates as $t) : ?><option value="<?= e($t['public_id']) ?>"<?= old('template') === $t['public_id'] ? ' selected' : '' ?>><?= e($t['name']) ?> (v<?= (int) $t['current_version'] ?>)</option><?php endforeach; ?></select></div>
    <div class="field"><label for="b">Agreement text <span class="muted">(when not using a template; placeholders like {{client_name}} work here too)</span></label><textarea id="b" name="body" rows="12" maxlength="60000"><?= e(old('body')) ?></textarea></div>
    <div class="field"><label for="e">Offer expires on <span class="muted">(optional)</span></label><input id="e" name="expires_on" type="date" value="<?= e(old('expires_on')) ?>"></div>
    <div class="form-actions"><button class="btn btn-primary" type="submit">Save draft</button></div></form>
